//! Windows keys to Linux evdev keycodes, the set of keys held, and the
//! release chord. Pure: nothing here touches Win32.
//!
//! The tables are `match` expressions, one arm per key with its Linux name,
//! generated by `scripts/gen-keymap.py` from the keycodemapdb data in
//! `tests/fixtures/set1-evdev.tsv` (BSD-3-Clause option, with its notice
//! beside it). A test compares every arm with that fixture.

use std::collections::BTreeSet;
use std::fmt;
use std::str::FromStr;

/// A Linux evdev keycode (`input-event-codes.h`).
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Evdev(pub u16);

impl Evdev {
    pub const ESC: Self = Self(1);
    pub const KEY_L: Self = Self(38);
    pub const LEFT_CTRL: Self = Self(29);
    pub const LEFT_SHIFT: Self = Self(42);
    pub const RIGHT_SHIFT: Self = Self(54);
    pub const LEFT_ALT: Self = Self(56);
    pub const RIGHT_CTRL: Self = Self(97);
    pub const RIGHT_ALT: Self = Self(100);
    pub const HOME: Self = Self(102);
    pub const LEFT_META: Self = Self(125);
    pub const RIGHT_META: Self = Self(126);
    pub const NUM_LOCK: Self = Self(69);
    pub const PAUSE: Self = Self(119);
    pub const SYSRQ: Self = Self(99);
}

/// Whether the E0 prefix was set (`LLKHF_EXTENDED`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Prefix {
    None,
    E0,
}

/// A key going down or up.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Press {
    Down,
    Up,
}

/// One evdev key event.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KeyEvent {
    pub key: Evdev,
    pub press: Press,
}

/// `VK_PAUSE`: Windows reports Pause with the scan code of Num Lock.
pub const VK_PAUSE: u16 = 0x13;
/// `VK_NUMLOCK`.
pub const VK_NUMLOCK: u16 = 0x90;

/// Windows key to evdev. The virtual key decides only where the scan code is
/// ambiguous (0x45 is both Pause and Num Lock). Scan code 0 (a key injected
/// by VK only), E0 2A, and a scan code above one byte give `None`. Windows
/// sets the "simulated" bit, 0x200, in the scan code of the events it makes
/// up (the fake shifts 0x22A and 0x236 around a keypad key with Num Lock on,
/// the fake Ctrl 0x21D of AltGr), so those are above one byte. A real right
/// Shift is E0 36 and is `KEY_RIGHTSHIFT`; a fake one without the simulated
/// bit would look the same, which is an open decision. F13 to F24 fall back to
/// the VK. Total: it never panics.
pub fn evdev(vk: u16, scan: u16, prefix: Prefix) -> Option<Evdev> {
    let scan = u8::try_from(scan).ok()?;
    if scan == 0 {
        return None;
    }
    let mapped = match prefix {
        Prefix::None if scan == 0x45 && vk == VK_PAUSE => Some(Evdev::PAUSE.0),
        Prefix::None if scan == 0x45 && vk == VK_NUMLOCK => Some(Evdev::NUM_LOCK.0),
        Prefix::None => normal(scan),
        Prefix::E0 => e0(scan),
    };
    match (mapped, prefix) {
        (Some(code), _) => Some(Evdev(code)),
        // The Copilot key sends F23 with a scan code the table lacks.
        (None, Prefix::None) => function_key_by_vk(vk),
        (None, Prefix::E0) => None,
    }
}

/// F13 to F24 by virtual key (`VK_F13` is 0x7c), for keys whose scan code is
/// not in the table.
const fn function_key_by_vk(vk: u16) -> Option<Evdev> {
    match vk {
        0x7c..=0x87 => Some(Evdev(183 + (vk - 0x7c))),
        _ => None,
    }
}

