/// The keys held now, so an Up is sent only for a Down that was sent, and an
/// auto-repeat is not sent twice (upstream's `track_key`, `main.rs:1551-1561`).
#[derive(Debug, Default)]
pub struct KeyState {
    held: BTreeSet<Evdev>,
}

impl KeyState {
    /// `None` for an auto-repeat Down of a held key and for an Up of a key
    /// that is not held.
    pub fn apply(&mut self, event: KeyEvent) -> Option<KeyEvent> {
        let changed = match event.press {
            Press::Down => self.held.insert(event.key),
            Press::Up => self.held.remove(&event.key),
        };
        changed.then_some(event)
    }

    /// An Up for every held key, and the set is empty afterwards.
    pub fn release_all(&mut self) -> Vec<KeyEvent> {
        std::mem::take(&mut self.held)
            .into_iter()
            .map(|key| KeyEvent {
                key,
                press: Press::Up,
            })
            .collect()
    }

    pub fn is_held(&self, key: Evdev) -> bool {
        self.held.contains(&key)
    }

    pub fn is_any_held(&self, keys: &[Evdev]) -> bool {
        keys.iter().any(|k| self.held.contains(k))
    }

    /// The keys of `keys` that are held, in code order.
    pub fn held_among(&self, keys: &[Evdev]) -> Vec<Evdev> {
        self.held
            .iter()
            .copied()
            .filter(|k| keys.contains(k))
            .collect()
    }

    pub fn is_empty(&self) -> bool {
        self.held.is_empty()
    }

    /// How many keys are held.
    pub fn len(&self) -> usize {
        self.held.len()
    }
}

/// Why a chord string did not parse.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ChordError {
    #[error("the chord is empty")]
    Empty,
    #[error("unknown key {0:?} in the chord")]
    UnknownKey(String),
}

/// One slot of a chord: any of these keys satisfies it (Ctrl is either Ctrl).
/// `name` is the canonical spelling, so that `Control` and `ctrl` are one slot.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Slot {
    keys: Vec<Evdev>,
    name: String,
}

/// A chord such as `Ctrl+Alt+Home`: modifiers match either side, and the
/// last slot is the trigger.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Chord {
    slots: Vec<Slot>,
}

impl Chord {
    /// Ctrl+Alt+Home, the default release chord (decision 8).
    pub fn ctrl_alt_home() -> Self {
        "ctrl+alt+home".parse().expect("the default chord parses")
    }

    /// Ctrl+Alt+L, the default Super+L stand-in chord.
    pub fn ctrl_alt_l() -> Self {
        "ctrl+alt+l".parse().expect("the default chord parses")
    }

    /// Ctrl+Alt+PageDown, the default chord for the next tab.
    pub fn ctrl_alt_page_down() -> Self {
        "ctrl+alt+pagedown"
            .parse()
            .expect("the default chord parses")
    }

    /// Ctrl+Alt+PageUp, the default chord for the previous tab.
    pub fn ctrl_alt_page_up() -> Self {
        "ctrl+alt+pageup".parse().expect("the default chord parses")
    }

    /// True when `event` is the Down of the trigger key and every other slot
    /// has a key held in `state`. The trigger is not forwarded.
    pub fn completes(&self, state: &KeyState, event: KeyEvent) -> bool {
        if event.press != Press::Down {
            return false;
        }
        let Some((trigger, modifiers)) = self.slots.split_last() else {
            return false;
        };
        trigger.keys.contains(&event.key)
            && !state.is_held(event.key)
            && modifiers.iter().all(|slot| state.is_any_held(&slot.keys))
    }

    /// The keys of every non-trigger slot, so a caller can release them.
    pub fn modifier_keys(&self) -> Vec<Evdev> {
        let Some((_, modifiers)) = self.slots.split_last() else {
            return Vec::new();
        };
        modifiers
            .iter()
            .flat_map(|slot| slot.keys.clone())
            .collect()
    }

    /// The keys that complete the chord when they go down.
    pub fn trigger_keys(&self) -> &[Evdev] {
        self.slots.last().map_or(&[], |slot| slot.keys.as_slice())
    }

    /// The modifier families among the non-trigger slots. A slot that is not
    /// a modifier (`a+b+c`) is left out.
    pub fn modifiers(&self) -> ModifierSet {
        let Some((_, modifiers)) = self.slots.split_last() else {
            return ModifierSet::default();
        };
        modifiers
            .iter()
            .filter_map(|slot| ModifierSet::from_word(&slot.name))
            .fold(ModifierSet::default(), ModifierSet::with)
    }
}

impl fmt::Display for Chord {
    /// The canonical spelling, which parses back to an equal chord.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let names: Vec<&str> = self.slots.iter().map(|s| s.name.as_str()).collect();
        f.write_str(&names.join("+"))
    }
}

/// A set of modifier families, each standing for its left and right key.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ModifierSet(u8);

/// Why a modifier list did not parse.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ModifierSetError {
    #[error("the list of modifiers is empty")]
    Empty,
    #[error("{0:?} is not a modifier (ctrl, alt, shift, win)")]
    NotAModifier(String),
}

impl ModifierSet {
    pub const CTRL: Self = Self(1);
    pub const ALT: Self = Self(2);
    pub const SHIFT: Self = Self(4);
    pub const WIN: Self = Self(8);

    /// The bits, for code that keeps the families in a plain byte.
    pub(crate) const fn bits(self) -> u8 {
        self.0
    }

    pub(crate) const fn from_bits(bits: u8) -> Self {
        Self(bits & 15)
    }

    pub const fn with(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }

    /// The family of a canonical chord word, if it is a modifier.
    fn from_word(word: &str) -> Option<Self> {
        match word {
            "ctrl" => Some(Self::CTRL),
            "alt" => Some(Self::ALT),
            "shift" => Some(Self::SHIFT),
            "win" => Some(Self::WIN),
            _ => None,
        }
    }

    pub fn is_empty(self) -> bool {
        self.0 == 0
    }

    /// True when every family of `self` is also in `other`.
    pub fn is_subset_of(self, other: Self) -> bool {
        self.0 & !other.0 == 0
    }
}

impl fmt::Display for ModifierSet {
    /// `win+ctrl+alt+shift` order (as Windows writes them), only the families in the set.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let names: Vec<&str> = [
            (Self::WIN, "win"),
            (Self::CTRL, "ctrl"),
            (Self::ALT, "alt"),
            (Self::SHIFT, "shift"),
        ]
        .into_iter()
        .filter(|(family, _)| family.is_subset_of(*self))
        .map(|(_, name)| name)
        .collect();
        f.write_str(&names.join("+"))
    }
}

impl FromStr for ModifierSet {
    type Err = ModifierSetError;

    /// Modifiers joined by `+`, such as `ctrl+alt`; at least one.
    fn from_str(text: &str) -> Result<Self, ModifierSetError> {
        let mut set = Self::default();
        for word in text.split('+').map(str::trim).filter(|w| !w.is_empty()) {
            let canonical = canonical_name(&word.to_ascii_lowercase());
            let family = Self::from_word(&canonical)
                .ok_or_else(|| ModifierSetError::NotAModifier(word.to_owned()))?;
            set = set.with(family);
        }
        if set.is_empty() {
            return Err(ModifierSetError::Empty);
        }
        Ok(set)
    }
}

impl FromStr for Chord {
    type Err = ChordError;

    fn from_str(text: &str) -> Result<Self, ChordError> {
        let mut slots = Vec::new();
        for name in text.split('+').map(str::trim).filter(|n| !n.is_empty()) {
            let lower = name.to_ascii_lowercase();
            let keys =
                keys_by_name(&lower).ok_or_else(|| ChordError::UnknownKey(name.to_string()))?;
            slots.push(Slot {
                keys,
                name: canonical_name(&lower),
            });
        }
        if slots.is_empty() {
            return Err(ChordError::Empty);
        }
        Ok(Self { slots })
    }
}

/// The one spelling of a chord word that has several (`control` is `ctrl`,
/// `pgdn` is `pagedown`, `f01` is `f1`).
fn canonical_name(name: &str) -> String {
    let canonical = match name {
        "control" => "ctrl",
        "super" | "meta" => "win",
        "escape" => "esc",
        "pgup" => "pageup",
        "pgdn" => "pagedown",
        "ins" => "insert",
        "del" => "delete",
        "return" => "enter",
        other => {
            if let Some(number) = other.strip_prefix('f').and_then(|n| n.parse::<u16>().ok()) {
                return format!("f{number}");
            }
            other
        }
    };
    canonical.to_owned()
}

/// The evdev keys behind a chord word; modifiers give both sides.
fn keys_by_name(name: &str) -> Option<Vec<Evdev>> {
    let one = |code: u16| Some(vec![Evdev(code)]);
    match name {
        "ctrl" | "control" => Some(vec![Evdev::LEFT_CTRL, Evdev::RIGHT_CTRL]),
        "alt" => Some(vec![Evdev::LEFT_ALT, Evdev::RIGHT_ALT]),
        "shift" => Some(vec![Evdev::LEFT_SHIFT, Evdev::RIGHT_SHIFT]),
        "super" | "win" | "meta" => Some(vec![Evdev::LEFT_META, Evdev::RIGHT_META]),
        "esc" | "escape" => one(1),
        "home" => one(102),
        "end" => one(107),
        "pgup" | "pageup" => one(104),
        "pgdn" | "pagedown" => one(109),
        "insert" | "ins" => one(110),
        "delete" | "del" => one(111),
        "backspace" => one(14),
        "tab" => one(15),
        "enter" | "return" => one(28),
        "space" => one(57),
        "up" => one(103),
        "left" => one(105),
        "right" => one(106),
        "down" => one(108),
        "pause" => one(119),
        _ => key_by_letter_digit_or_f(name),
    }
}

/// `a`..`z`, `0`..`9`, `f1`..`f24`.
fn key_by_letter_digit_or_f(name: &str) -> Option<Vec<Evdev>> {
    const LETTERS: [u16; 26] = [
        30, 48, 46, 32, 18, 33, 34, 35, 23, 36, 37, 38, 50, 49, 24, 25, 16, 19, 31, 20, 22, 47, 17,
        45, 21, 44,
    ];
    let bytes = name.as_bytes();
    if let [c @ b'a'..=b'z'] = bytes {
        return Some(vec![Evdev(LETTERS[usize::from(c - b'a')])]);
    }
    if let [c @ b'0'..=b'9'] = bytes {
        let code = if *c == b'0' {
            11
        } else {
            2 + u16::from(c - b'1')
        };
        return Some(vec![Evdev(code)]);
    }
    let number: u16 = name.strip_prefix('f')?.parse().ok()?;
    let code = match number {
        1..=10 => 59 + (number - 1),
        11 => 87,
        12 => 88,
        13..=24 => 183 + (number - 13),
        _ => return None,
    };
    Some(vec![Evdev(code)])
}

